(() => {
  'use strict';
  const STORAGE='idearoute-maket-v1', DRAFT='idearoute-maket-draft-v1';
  const TODAY='2026-11-12', NOW='2026-11-12T11:30:00+05:00';
  const statuses={new:'Новое',review:'На рассмотрении',waiting:'Ожидает уточнения',progress:'В работе',implemented:'Реализовано',rejected:'Отклонено',closed:'Закрыто'};
  const roles={employee:'Сотрудник',manager:'Руководитель',admin:'Администратор'};
  const identities={employee:'Сотрудник закупок',manager:'Руководитель направления',admin:'Администратор системы'};
  const owners=['Руководитель закупок','Руководитель направления','Ответственный за номенклатуру','Ответственный за обучение','Руководитель бухгалтерии','Ответственный за процессы','IT-специалист','Руководитель подразделения','Ответственный за договоры','Руководитель продаж','Руководитель проектов','Руководитель проектирования','Административный руководитель','HR / внутренние коммуникации','Администратор документов'];
  let db, role='manager', direction='Операционные процессы', mobileOpen=false, selectedId=null, view='overview', board=false, activeTab='attention';
  let filters={q:'',status:'',category:'',department:'',deadline:''}, attachments=[],toastTimer,lastModalFocus;
  try { const prefs=JSON.parse(sessionStorage.getItem('idearoute-maket-context')||'{}');if(roles[prefs.role])role=prefs.role;if(['Операционные процессы','IT и данные'].includes(prefs.direction))direction=prefs.direction; } catch {}
  try { db=JSON.parse(localStorage.getItem(STORAGE)); } catch { /* Storage may be unavailable for file URLs. */ }
  if(!db||db.version!==1||!Array.isArray(db.records))db=structuredClone(window.IDEAROUTE_SEED);
  const el=id=>document.getElementById(id);
  const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon=(name,cls='')=>`<i data-lucide="${name}" class="${cls}" aria-hidden="true"></i>`;
  const closed=r=>['implemented','rejected','closed'].includes(r.status);
  const complete=r=>closed(r)&&!!r.decision;
  const overdue=r=>!closed(r)&&r.due<TODAY;
  const readable=r=>role==='admin'||(role==='employee'?r.author===identities.employee:r.direction===direction&&!!r.owner);
  const visible=()=>db.records.filter(readable);
  const manageable=r=>role==='manager'&&readable(r);
  const fmt=d=>new Date(d.includes('T')?d:d+'T12:00:00+05:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short',timeZone:'Asia/Qyzylorda'}).replace(' г.','');
  const time=d=>new Date(d).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Qyzylorda'});
  const pct=(n,total)=>total?Math.round(n/total*100)+'%':'—';
  const avg=a=>a.length?(a.reduce((s,n)=>s+n,0)/a.length).toFixed(1).replace('.',','):'—';
  const initials=s=>s.split(' ').slice(0,2).map(w=>w[0]).join('').toUpperCase();
  const statusBadge=r=>`<span class="badge ${r.status}">${statuses[r.status]}</span>`;
  const typeIcon=r=>`<span class="type-icon ${r.type==='Предложение'?'idea':r.type==='Положительный отзыв'?'positive':''}">${icon(r.type==='Проблема'?'message-square-warning':r.type==='Предложение'?'lightbulb':'heart-handshake')}</span>`;
  const btn=(text,action,style='',extra='')=>`<button class="btn ${style}" data-action="${action}" ${extra}>${text}</button>`;
  const opts=(items,value,placeholder)=>`${placeholder!==undefined?`<option value="">${placeholder}</option>`:''}${items.map(item=>{const val=typeof item==='string'?item:item.value;const label=typeof item==='string'?item:item.label;return `<option value="${escape(val)}" ${val===value?'selected':''}>${escape(label)}</option>`;}).join('')}`;
  const routeFor=category=>db.rules.find(r=>r.category===category&&r.active&&r.owner);
  function save(){try{localStorage.setItem(STORAGE,JSON.stringify(db));}catch{toast('Память браузера заполнена. Изменения доступны до закрытия страницы.');}}
  function toast(text){el('toast').textContent=text;el('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el('toast').classList.remove('visible'),3800);}
  function hydrate(){if(window.lucide)window.lucide.createIcons({attrs:{'stroke-width':1.65}});}
  function event(r,text,kind='status'){r.history.push({at:NOW,actor:identities[role],text,kind});}
  function notify(r,target,title,text){db.notifications.unshift({id:'n'+Date.now()+Math.random(),caseId:r.id,role:target,title,text,read:false});}
  function notifications(){return db.notifications.filter(n=>n.role===role&&db.records.some(r=>r.id===n.caseId&&readable(r)));}
  function go(target){if(location.hash==='#'+target)render();else location.hash=target;}
  function getRoute(){const pieces=location.hash.slice(1).split('/');view=pieces[0]||'overview';selectedId=pieces[1]||null;if(!['overview','cases','new','case','results','analytics','categories','routing','notifications','help'].includes(view))view='overview';if(role!=='admin'&&['categories','routing'].includes(view))view='overview';if(role==='employee'&&view==='analytics')view='overview';if(role!=='employee'&&view==='new')view='overview';}
  function needAction(r){return role==='employee'?r.status==='waiting':role==='admin'?!r.owner&&!closed(r):r.status==='new'||overdue(r);}
  function dueLabel(r){if(closed(r))return `<span class="due muted">${fmt(r.closedAt||r.created)}</span>`;if(overdue(r))return `<span class="due red">${icon('clock-alert')} ${Math.ceil((new Date(TODAY)-new Date(r.due))/86400000)} д. просрочки</span>`;return `<span class="due ${r.due===TODAY?'amber':'muted'}">${r.due===TODAY?'Сегодня':fmt(r.due)}</span>`;}
  function titleBlock(eyebrow,title,subtitle,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
  function navLink(target,label,ic,count=0){return `<button class="nav-link ${view===target||(target==='cases'&&view==='case')?'active':''}" data-action="nav" data-to="${target}" ${view===target?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${count?`<span class="nav-count">${count}</span>`:''}</button>`;}
  function shell(content){const records=visible(), unread=notifications().filter(n=>!n.read).length;const names={overview:'Обзор',cases:role==='employee'?'Мои обращения':'Реестр обращений',case:'Карточка обращения',new:'Новое обращение',results:'Результаты',analytics:'Аналитика',categories:'Категории',routing:'Маршрутизация',notifications:'Уведомления',help:'О макете и сценариях'};
    return `<div class="mobile-scrim ${mobileOpen?'open':''}" data-action="menu"></div><aside class="sidebar ${mobileOpen?'open':''}" aria-label="Основная навигация"><a href="#overview" class="brand-lockup"><span class="brand-mark">${icon('route')}</span><span>Idea<span style="font-weight:500">Route</span></span></a><div class="workspace"><span class="workspace-avatar">МТ</span><div><div style="font-size:11px;font-weight:750">Модус Трейд</div><div class="subtle" style="font-size:9px">Рабочее пространство</div></div>${icon('chevrons-up-down','ml-auto text-muted w-3')}</div><nav class="flex-1 overflow-y-auto"><div class="nav-group"><div class="eyebrow">Рабочее пространство</div>${navLink('overview','Обзор','layout-dashboard')}${navLink('cases',role==='employee'?'Мои обращения':'Обращения','inbox',records.filter(r=>!closed(r)).length)}${role==='employee'?navLink('new','Новое обращение','circle-plus'):''}${navLink('results','Результаты','circle-check-big',records.filter(complete).length)}${role!=='employee'?navLink('analytics','Аналитика','chart-no-axes-combined'):''}</div>${role==='admin'?`<div class="nav-group"><div class="eyebrow">Управление системой</div>${navLink('categories','Категории','tags')}${navLink('routing','Маршрутизация','git-branch',db.records.filter(r=>!r.owner&&!closed(r)).length)}</div>`:''}<div class="nav-group"><div class="eyebrow">Личное</div>${navLink('notifications','Уведомления','bell',unread)}</div></nav><div class="side-bottom"><div class="side-manifesto"><div class="flex gap-2 items-center brand i-sm">${icon('route')}<span style="font-size:11px;font-weight:750">От идеи к результату</span></div><p>У каждого обращения —<br>ответственный и понятный итог.</p><button data-action="nav" data-to="help" class="btn ghost sm" style="margin-top:7px;color:#947ab2">Как устроен маршрут ${icon('arrow-up-right')}</button></div><div class="side-user"><span class="avatar">${role==='employee'?'СЗ':role==='manager'?'РН':'АС'}</span><div><div style="font-size:10px;font-weight:700">${identities[role]}</div><div class="subtle" style="font-size:9px">${role==='employee'?'Закупки':role==='manager'?'Внутренние процессы':'Настройки и маршруты'}</div></div></div></div></aside><div class="shell"><header class="topbar"><div class="flex items-center gap-3 min-w-0"><button class="icon-button mobile-menu" data-action="menu" aria-label="Открыть меню" aria-expanded="${mobileOpen}">${icon('menu')}</button><div class="crumbs"><span class="crumb-root">Рабочее пространство</span><span class="crumb-root">/</span><strong>${names[view]}</strong></div></div><div class="top-actions"><button class="btn ghost global-search muted i-sm" data-action="search">${icon('search')}<span style="font-weight:400;font-size:10px">Найти обращение</span><kbd class="subtle" style="margin-left:14px;font-size:9px">/</kbd></button><span class="demo-pill">ДЕМО</span><select class="role-select" aria-label="Роль в демонстрации" data-change="role">${opts(Object.entries(roles).map(([value,label])=>({value,label})),role)}</select><button class="icon-button" data-action="nav" data-to="notifications" aria-label="Уведомления${unread?' — есть непрочитанные':''}">${icon('bell')}${unread?'<span class="notification-dot"></span>':''}</button></div></header><main id="main" tabindex="-1" class="content">${content}<footer class="footer-note"><div>${icon('lock-keyhole')} ${role==='employee'?'Видны только ваши обращения':role==='manager'?'Видны обращения вашего направления':'Доступны внутренние обращения и настройки'}<br><button data-action="nav" data-to="help">Интерактивный макет · синтетические данные</button></div><span>IdeaRoute / Feedback Operations</span></footer></main></div>`;
  }
  function scope(){return `<div class="context-line"><div class="flex items-center gap-2 i-sm">${icon('building-2')}${role==='manager'?`<select aria-label="Направление руководителя" class="context-select" data-change="direction">${opts(['Операционные процессы','IT и данные'],direction)}</select>`:role==='employee'?'Мой рабочий маршрут · Закупки':'Все подразделения'}<span class="muted">·</span><span>${visible().length} обращений</span></div><span class="flex items-center gap-2 i-sm">${icon('calendar-days')} 1–12 ноября 2026 <span class="tiny-pill">Демо-период</span></span></div>`;}
  function metric(label,value,note,ic,action,extra='',tone=''){return `<button class="card metric" data-action="${action}" ${extra}><div class="flex justify-between gap-2 items-center"><span class="metric-label">${label}</span><span class="metric-icon ${tone}">${icon(ic)}</span></div><div class="metric-value mono ${tone}">${value}</div><div class="metric-note">${note}</div></button>`;}
  function overview(){const rows=visible(),done=rows.filter(complete),active=rows.filter(r=>!closed(r)),attention=rows.filter(needAction),late=rows.filter(overdue),implemented=rows.filter(r=>r.status==='implemented');
    const heading=role==='employee'?['ВАШИ ИДЕИ И ОБРАТНАЯ СВЯЗЬ','Изменения начинаются с вас.','Расскажите о проблеме. Предложите улучшение. Следите за результатом.']:role==='admin'?['НАДЁЖНЫЙ МАРШРУТ ОБРАЩЕНИЙ','Ни одно обращение не потеряется.','Настройте категории, ответственных и правила передачи обращений.']:['ОБРАТНАЯ СВЯЗЬ СОТРУДНИКОВ','Каждое обращение — к результату.','Помогайте предложениям двигаться вперёд, а проблемам — находить решение.'];
    const action=role==='employee'?btn(icon('plus')+'Новое обращение','nav','primary','data-to="new"'):role==='admin'?btn(icon('git-branch')+'Настроить маршруты','nav','primary','data-to="routing"'):btn('Рассмотреть обращения '+icon('arrow-up-right'),'queue','primary');
    let queue=activeTab==='overdue'?late:activeTab==='all'?active:attention;queue=queue.slice().sort((a,b)=>(overdue(b)-overdue(a))||a.due.localeCompare(b.due));
    return `${titleBlock(...heading,action)}${scope()}<div class="metric-grid grid grid-cols-4 gap-4 mb-5">${metric('В работе и на рассмотрении',active.length,'обращений ждут своего результата','inbox','filter','data-filter="open"')}${metric(role==='employee'?'Нужен ваш ответ':role==='admin'?'Без ответственного':'Требуют внимания',attention.length,role==='employee'?'руководитель запросил уточнение':role==='admin'?'в резервной очереди администратора':`${late.length} с нарушенным сроком рассмотрения`,'clock-alert','queue','',attention.length?'amber':'')}${metric('С зафиксированным решением',pct(done.length,rows.length),`${done.length} из ${rows.length} · результат доступен автору`,'circle-check-big','nav','data-to="results"')}${metric('Реализовано улучшений',implemented.length,'подтверждённые действия и результаты','lightbulb','filter','data-filter="implemented"','green')}</div><div class="overview-route grid grid-cols-[minmax(0,1fr)_230px] gap-5 mb-5"><section class="card route-card"><div class="card-head"><div><h2>Маршрут обращения</h2><p>Понятный следующий шаг на каждом этапе</p></div><span class="tiny-pill">От идеи к результату</span></div><div class="route-stages">${[['new','Получено','Категория и маршрут'],['review','Рассмотрение','Ответственный назначен'],['waiting','Уточнение','Диалог с автором'],['progress','Действия','Решение выполняется'],['done','Результат','Ответ опубликован']].map(([s,label,note],i)=>{const count=s==='done'?done.length:rows.filter(r=>r.status===s).length;return `<button class="route-stage" data-action="filter" data-filter="${s}" aria-label="${label}: ${count} обращений"><div class="stage-top"><span>0${i+1}</span>${icon(i===4?'circle-check':'arrow-right')}</div><div class="stage-number mono">${count.toString().padStart(2,'0')}</div><div class="stage-name">${label}</div><div class="stage-meta">${note}</div><div class="stage-line"><span style="width:${rows.length?Math.max(8,count/rows.length*100):0}%"></span></div></button>`;}).join('')}</div><div class="route-foot">${icon('info')}Решение, действия и ответ автору сохраняются в одной истории.</div></section><section class="card loop-card"><div><div class="eyebrow" style="color:#a08bbd;font-size:8px">Цикл обратной связи</div><h2 style="margin-top:8px">Результат есть.<br>Ответ доступен автору.</h2></div><div><div class="flex items-end gap-2"><span class="loop-number mono">${done.length}</span><span class="subtle" style="padding-bottom:5px">из ${rows.length} обращений</span></div><div class="progress-track"><span style="width:${rows.length?done.length/rows.length*100:0}%"></span></div><div class="loop-check">${icon('check')}Решение зафиксировано</div><div class="loop-check">${icon('check')}Ответ доступен в кабинете</div><button class="btn ghost sm" data-action="nav" data-to="results" style="color:#9377b3;margin-top:5px">Посмотреть результаты ${icon('arrow-right')}</button></div></section></div><div class="overview-bottom grid grid-cols-[minmax(0,1fr)_295px] gap-5 items-start"><section class="card"><div class="card-head"><div><h2>${role==='employee'?'Ваш следующий шаг':'В фокусе внимания'}</h2><p>${role==='employee'?'Уточнения и обращения, по которым ещё нет результата':'Начните с обращений, которым нужно ваше действие'}</p></div>${btn(icon('arrow-up-right'),'nav','ghost','data-to="cases" aria-label="Открыть весь реестр"')}</div><div class="tabs">${[['attention',role==='employee'?'Нужен ответ':role==='admin'?'Без назначения':'Требуют внимания',attention.length],['overdue','Просрочены',late.length],['all','Все активные',active.length]].map(([id,label,count])=>`<button class="tab ${activeTab===id?'active':''}" data-action="overview-tab" data-tab="${id}">${label}<span>${count}</span></button>`).join('')}</div>${caseTable(queue.slice(0,4),true)}<div class="table-foot"><span>${queue.length?'Показано '+Math.min(4,queue.length)+' из '+queue.length:'Все обращения под контролем'}</span><button class="brand" data-action="nav" data-to="cases">Перейти в реестр ${icon('arrow-right')}</button></div></section><div class="overview-side space-y-5"><section class="card"><div class="card-head"><div><h2>Последние результаты</h2><p>Что изменилось благодаря обратной связи</p></div>${icon('circle-check-big','green')}</div>${done.length?done.slice().sort((a,b)=>new Date(b.closedAt)-new Date(a.closedAt)).slice(0,2).map(resultMini).join(''):empty('Пока нет результатов','Здесь появятся опубликованные решения.','circle-check-big')}</section><section class="card repeat-card"><div class="flex justify-between items-center"><h3>Повторяющаяся тема</h3>${icon('layers-2','brand')}</div><p>${role==='employee'?'Похожие обращения объединяются в общую тему. Ваш ответ и история сохраняются.':'Полнота постановки задач: заявки и поручения без обязательных данных.'}</p><div class="flex justify-between items-center"><span class="tiny-pill">${rows.filter(r=>r.related.length).length} связанных обращения</span><button class="btn ghost sm" data-action="${role==='employee'?'nav':'related'}" data-to="help" aria-label="Посмотреть повторяющуюся тему">${icon('arrow-up-right')}</button></div></section></div></div>`;
  }
  function empty(title,text,ic='inbox'){return `<div class="empty">${icon(ic)}<h3>${title}</h3><p>${text}</p></div>`;}
  function resultMini(r){return `<button class="result-item" data-action="open" data-id="${r.id}"><div class="flex justify-between items-center">${statusBadge(r)}<span class="case-id">${r.id}</span></div><h3>${escape(r.title)}</h3><p>${escape(r.decision)}</p><div class="flex items-center gap-1.5 mt-2 green i-sm" style="font-size:9px">${icon(r.readByAuthor?'check-check':'send')}${r.readByAuthor?'Автор ознакомился':'Ответ опубликован для автора'}</div></button>`;}
  function caseTable(rows,compact=false){if(!rows.length)return empty('Здесь пока нет обращений','Измените фильтры или перейдите ко всем обращениям.');return `<div class="table-scroll"><table class="case-table"><thead><tr><th>ОБРАЩЕНИЕ</th><th>СТАТУС</th>${compact?'':'<th>ОТВЕТСТВЕННЫЙ</th><th>ПОДРАЗДЕЛЕНИЕ</th>'}<th>${compact?'СРОК':'СРОК / ЗАВЕРШЕНИЕ'}</th><th><span class="sr-only">Действие</span></th></tr></thead><tbody>${rows.map(r=>`<tr><td><div class="flex gap-3 items-start">${typeIcon(r)}<div><button class="case-title" data-action="open" data-id="${r.id}">${escape(r.title)}</button><div class="case-caption"><span class="case-id">${r.id}</span> &nbsp;·&nbsp; ${escape(r.category)}</div></div></div></td><td>${statusBadge(r)}${r.status==='waiting'?`<div class="case-caption">${role==='employee'?'Ответьте на уточнение':'Ждём ответа автора'}</div>`:''}</td>${compact?'':`<td><div class="flex items-center gap-2">${r.owner?`<span class="avatar small">${initials(r.owner)}</span><span style="font-size:10px;max-width:130px">${escape(r.owner)}</span>`:'<span class="amber">Резервная очередь</span>'}</div></td><td><span style="font-size:10px" class="muted">${r.department}</span></td>`}<td>${dueLabel(r)}</td><td><button class="icon-button" data-action="open" data-id="${r.id}" aria-label="Открыть ${r.id}">${icon('arrow-up-right')}</button></td></tr>`).join('')}</tbody></table></div>`;}
  function filtered(){return visible().filter(r=>(!filters.q||[r.id,r.title,r.description,r.category,r.decision,r.owner].join(' ').toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.status||(filters.status==='open'?!closed(r):filters.status==='done'?complete(r):r.status===filters.status))&&(!filters.category||(filters.category==='__related'?r.related.length>0:r.category===filters.category))&&(!filters.department||r.department===filters.department)&&(!filters.deadline||(filters.deadline==='overdue'?overdue(r):filters.deadline==='today'?!closed(r)&&r.due===TODAY:filters.deadline==='unassigned'?!r.owner&&!closed(r):true))).sort((a,b)=>(overdue(b)-overdue(a))||a.due.localeCompare(b.due));}
  function tableOrBoard(){const rows=filtered();return board?`<div class="board">${[['new','Получено'],['review','Рассмотрение'],['waiting','Уточнение'],['progress','Действия'],['done','Результат']].map(([s,label])=>{const group=rows.filter(r=>s==='done'?closed(r):r.status===s);return `<section class="board-col"><div class="flex items-center justify-between"><h2 style="font-size:11px;font-weight:650">${label}</h2><span class="tiny-pill">${group.length}</span></div>${group.map(r=>`<button class="board-card" data-action="open" data-id="${r.id}"><div class="flex justify-between items-center"><span class="case-id">${r.id}</span>${typeIcon(r)}</div><h3>${escape(r.title)}</h3>${statusBadge(r)}<div class="mt-3">${dueLabel(r)}</div></button>`).join('')}${!group.length?'<p class="subtle" style="margin-top:25px;text-align:center">Нет обращений</p>':''}</section>`;}).join('')}</div>`:caseTable(rows);}
  function cases(){const rows=visible();return `${titleBlock('ЕДИНАЯ ИСТОРИЯ ОБРАЩЕНИЙ',role==='employee'?'Мои обращения':'Реестр обращений',role==='employee'?'Статус, ответственный и следующий шаг — всегда под рукой.':'От регистрации до решения. Все доступные обращения в одном месте.',role==='employee'?btn(icon('plus')+'Новое обращение','nav','primary','data-to="new"'):btn(icon('download')+'Экспорт выборки','export'))}${scope()}${role==='admin'&&rows.some(r=>!r.owner&&!closed(r))?`<div class="attention-banner">${icon('git-pull-request')}<div><strong>Есть обращения без ответственного</strong><p>Они сохранены в резервной очереди. Назначьте маршрут, чтобы начать рассмотрение.</p></div>${btn('Открыть очередь','filter','sm ml-auto','data-filter="unassigned"')}</div>`:''}<section class="card"><div class="card-head"><div class="flex gap-2 flex-wrap">${[['','Все',rows.length],['new','Новые',rows.filter(r=>r.status==='new').length],['waiting','Уточнение',rows.filter(r=>r.status==='waiting').length],['overdue','Просрочены',rows.filter(overdue).length]].map(([s,label,count])=>btn(`${label} <span class="tiny-pill">${count}</span>`,'filter',((s==='overdue'?filters.deadline==='overdue':filters.status===s&&!filters.deadline)?'primary ':'')+'sm',`data-filter="${s}"`)).join('')}</div><div class="flex gap-1">${btn(icon('list'),'table-view',(!board?'primary ':'')+'sm','aria-label="Таблица" aria-pressed="'+!board+'"')}${btn(icon('columns-3'),'board-view',(board?'primary ':'')+'sm','aria-label="Доска" aria-pressed="'+board+'"')}</div></div><div class="filters"><label class="search-input">${icon('search')}<input id="case-search" aria-label="Поиск обращений" placeholder="Тема, номер или текст обращения…" value="${escape(filters.q)}"></label><select class="filter-select" aria-label="Фильтр по категории" data-filter-field="category">${opts([...new Set(rows.map(r=>r.category))],filters.category,'Все категории')}${filters.category==='__related'?'<option value="__related" selected>Связанные обращения</option>':''}</select><select class="filter-select" aria-label="Фильтр по подразделению" data-filter-field="department">${opts([...new Set(rows.map(r=>r.department))],filters.department,'Все подразделения')}</select><select class="filter-select" aria-label="Фильтр по статусу" data-filter-field="status">${opts(Object.entries(statuses).map(([value,label])=>({value,label})),filters.status,'Все статусы')}${['open','done'].includes(filters.status)?`<option value="${filters.status}" selected>${filters.status==='open'?'Все активные':'С результатом'}</option>`:''}</select><select class="filter-select" aria-label="Фильтр по сроку" data-filter-field="deadline">${opts([{value:'overdue',label:'Просроченные'},{value:'today',label:'Срок сегодня'},...(role==='admin'?[{value:'unassigned',label:'Без ответственного'}]:[])],filters.deadline,'Все сроки')}</select>${btn(icon('rotate-ccw'),'clear-filters','sm','aria-label="Сбросить фильтры"')}</div><div id="case-results">${tableOrBoard()}</div><div class="table-foot"><span id="result-count">Найдено ${filtered().length} из ${rows.length}</span><span>Нажмите на обращение, чтобы продолжить маршрут</span></div></section>`;}
  function results(){const rows=visible().filter(complete);return `${titleBlock('ЗАМКНУТЫЙ ЦИКЛ ОБРАТНОЙ СВЯЗИ','Результат, который виден.','Принятые решения, выполненные действия и обратная связь авторам.',btn('Все обращения '+icon('arrow-up-right'),'nav','','data-to="cases"'))}${scope()}<div class="attention-banner green-banner">${icon('circle-check-big')}<div><strong>Каждое обращение здесь имеет зафиксированный итог</strong><p>Результат опубликован для автора. Обоснованный отказ также завершает рассмотрение.</p></div></div><div class="grid md:grid-cols-2 gap-5">${rows.length?rows.slice().sort((a,b)=>new Date(b.closedAt)-new Date(a.closedAt)).map(r=>`<article class="card">${resultMini(r)}<div class="px-5 py-3 flex justify-between items-center subtle"><span>${escape(r.author)}</span><span>${fmt(r.closedAt||r.created)}</span></div></article>`).join(''):empty('Результаты появятся здесь','После публикации решения автор увидит его в своём кабинете.')}</div>`;}
  function draft(){try{return JSON.parse(localStorage.getItem(DRAFT))||{};}catch{return {};}}
  function newCase(){const d=draft();attachments=d.attachments||[];return `${titleBlock('ПЕРВЫЙ ШАГ К ИЗМЕНЕНИЯМ','Расскажите, что можно улучшить.','Вы описываете ситуацию. IdeaRoute помогает довести её до результата.',btn('Мои обращения','nav','','data-to="cases"'))}<div class="form-layout grid grid-cols-[minmax(0,1fr)_290px] gap-6 items-start"><form id="new-case-form" class="card form-card"><div class="form-step"><span class="step-token">01</span>Выберите тему обращения</div><div class="field-group"><label class="form-label" for="new-category">Категория <span class="brand">*</span></label><select id="new-category" name="category" required class="form-field">${opts(db.rules.filter(r=>!r.archived).map(r=>r.category),d.category,'Выберите категорию')}</select><p class="form-hint">От категории зависит маршрут к ответственному. Если не уверены, выберите «Другое».</p></div><fieldset class="field-group" style="border:0;padding:0"><legend class="form-label">Тип обращения</legend><div class="choice-grid">${[['Проблема','message-square-warning'],['Предложение','lightbulb'],['Положительный отзыв','heart-handshake']].map(([t,i])=>`<label class="choice"><input type="radio" name="type" value="${t}" ${(d.type||'Проблема')===t?'checked':''}>${icon(i)}${t}</label>`).join('')}</div></fieldset><div class="rule"></div><div class="form-step"><span class="step-token">02</span>Опишите ситуацию</div><div class="field-group"><label class="form-label" for="new-title">Короткая тема <span class="brand">*</span></label><input class="form-field" id="new-title" name="title" required minlength="5" maxlength="130" placeholder="Например, в заявках на оборудование не хватает параметров" value="${escape(d.title||'')}"></div><div class="field-group"><label class="form-label" for="new-description">Что произошло или что вы предлагаете? <span class="brand">*</span></label><textarea class="form-field" id="new-description" name="description" required minlength="15" maxlength="6000" rows="5" placeholder="Опишите ситуацию: где возникает, как влияет на работу и что хотелось бы изменить.">${escape(d.description||'')}</textarea><p class="form-hint">Не включайте коммерческие условия, персональные данные и другую закрытую информацию.</p></div><div class="field-group"><label class="form-label" for="new-proposed">Как это можно решить <span class="muted" style="font-weight:400">· необязательно</span></label><textarea class="form-field" id="new-proposed" name="proposed" maxlength="3000" rows="3" placeholder="Если у вас есть вариант решения, опишите его.">${escape(d.proposed||'')}</textarea></div><div class="upload-zone">${icon('paperclip')}<label for="new-files" style="display:block;margin-top:6px">Добавьте материалы, если они помогут разобраться</label><input id="new-files" type="file" accept=".pdf,.png,.jpg,.jpeg,.txt,.docx,.xlsx" multiple><div class="form-hint">До 3 файлов · до 1 МБ каждый · сохраняются только в этом браузере</div></div><div id="new-attachments" class="attachments">${attachmentDraft()}</div><div id="form-error" role="alert"></div><div class="rule"></div><div class="flex flex-wrap justify-between gap-3 items-center"><span class="form-hint" id="draft-status">Черновик сохраняется в браузере</span><div class="flex gap-2">${btn('Заполнить пример','sample','','type="button"')}<button type="submit" class="btn primary">Зарегистрировать ${icon('arrow-right')}</button></div></div></form><aside class="sticky-aside space-y-5"><div class="card flow-preview"><h2>Ваш маршрут к результату</h2><p class="form-hint">До отправки понятно, куда попадёт обращение.</p><div id="route-preview">${routePreview(d.category)}</div></div><div class="card flow-preview"><div class="flex items-center gap-2">${icon('shield-check','brand')}<h2>Кто увидит обращение</h2></div><p class="form-hint" style="margin-top:11px">Вы, ответственный, руководитель направления и администратор системы.</p><p class="form-hint">Подача от вашего имени: <strong>сотрудник закупок</strong>. Обращение не публикуется для всех сотрудников.</p></div><div class="px-2"><h3 style="font-size:11px;font-weight:650">Что будет после отправки?</h3><p class="form-hint">Вы получите номер обращения. Статус, комментарии и итог рассмотрения появятся в разделе «Мои обращения».</p></div></aside></div>`;}
  function routePreview(category){const rule=routeFor(category);return `<div class="v-step"><span class="v-step-icon">${icon('message-square-plus')}</span><div><strong>Регистрация обращения</strong><p>${escape(category||'Сначала выберите категорию')}</p></div></div><div class="v-step"><span class="v-step-icon">${icon('git-branch')}</span><div><strong>${rule?escape(rule.direction):category?'Резервная очередь':'Автоматическая маршрутизация'}</strong><p>${rule?escape(rule.owner):category?'Администратор назначит ответственного':'По выбранной категории'}</p></div></div><div class="v-step"><span class="v-step-icon">${icon('clock-3')}</span><div><strong>${rule?'Срок рассмотрения: '+rule.days+' дн.':category?'Контроль назначения: 1 день':'Срок будет определён правилом'}</strong><p>${rule?'Календарные дни · демонстрационное правило':'Обращение сохранится и не потеряется'}</p></div></div><div class="v-step"><span class="v-step-icon">${icon('circle-check-big')}</span><div><strong>Решение и обратная связь</strong><p>Результат в вашем личном кабинете</p></div></div>`;}
  function attachmentDraft(){return attachments.map((a,i)=>`<span class="attachment">${icon('file')} ${escape(a.name)} <button type="button" data-action="remove-file" data-index="${i}" aria-label="Удалить файл ${escape(a.name)}">${icon('x')}</button></span>`).join('');}
  function saveDraft(){const f=el('new-case-form');if(!f)return;const d=Object.fromEntries(new FormData(f));d.attachments=attachments;try{localStorage.setItem(DRAFT,JSON.stringify(d));el('draft-status').textContent='Черновик сохранён';}catch{el('draft-status').textContent='Черновик доступен до закрытия страницы';}}
  function detail(){const r=db.records.find(r=>r.id===selectedId);if(!r||!readable(r))return `${titleBlock('ДОСТУП К ОБРАЩЕНИЮ','Обращение недоступно.','В этой роли можно видеть только обращения в своей области доступа.',btn('К моим обращениям','nav','primary','data-to="cases"'))}${empty('Проверьте выбранную демо-роль','Сотруднику доступны свои обращения, руководителю — назначенные в его направление.','shield-check')}`;
    const stage=closed(r)?4:r.status==='progress'?3:r.status==='waiting'?2:r.status==='review'?1:0;
    const editable=manageable(r)&&!closed(r);
    return `<div class="detail-header"><button class="btn ghost back-link" data-action="nav" data-to="cases">${icon('arrow-left')} ${role==='employee'?'Мои обращения':'Реестр обращений'}</button><div class="flex items-center gap-2 mt-4"><span class="case-id">${r.id}</span><span class="muted">/</span><span class="subtle">${escape(r.category)}</span></div><h1>${escape(r.title)}</h1><div class="flex flex-wrap gap-3 items-center">${statusBadge(r)}<span class="subtle">${escape(r.type)}</span><span class="subtle">· ${fmt(r.created)}</span><span class="subtle">· ${escape(r.author)}</span>${r.related.length?'<span class="tiny-pill">Связано с общей темой</span>':''}</div></div><div class="detail-route">${[['Получено','inbox'],['Рассмотрение','scan-text'],['Уточнение','messages-square'],['Действия','list-checks'],['Результат','circle-check-big']].map(([label,ic],i)=>`<div class="detail-step ${i===stage?'current':i<stage?'done':''}">${icon(i<stage?'check':ic)}<span>${label}</span></div>`).join('')}</div>${r.status==='waiting'?`<div class="attention-banner">${icon('message-circle-question')}<div><strong>${role==='employee'?'Нужен ваш ответ':'Ожидаем уточнение от автора'}</strong><p>${escape(r.history.filter(h=>h.kind==='question').at(-1)?.text||r.nextAction)}</p></div>${role==='employee'?btn('Ответить','focus-comment','sm ml-auto'):''}</div>`:''}${!r.owner&&!closed(r)?`<div class="attention-banner">${icon('git-pull-request')}<div><strong>Обращение в резервной очереди</strong><p>Маршрут не найден. Администратор получил уведомление и назначит ответственного.</p></div>${role==='admin'?btn('Назначить маршрут','assign','primary sm ml-auto',`data-id="${r.id}"`):''}</div>`:''}<div class="detail-layout"><div class="space-y-5">${complete(r)?`<section class="card decision-block ${r.status==='rejected'?'rejected-result':''}"><div class="flex justify-between gap-3 items-center"><h2>${icon(r.status==='rejected'?'circle-minus':'circle-check-big')} ${r.status==='implemented'?'Улучшение реализовано':r.status==='rejected'?'Решение с объяснением':'Рассмотрение завершено'}</h2>${statusBadge(r)}</div><p>${escape(r.decision)}</p>${r.actions?`<div class="proposed"><h3>${r.status==='implemented'?'ЧТО СДЕЛАНО':'ДОПОЛНИТЕЛЬНЫЙ КОНТЕКСТ'}</h3><div class="body-copy">${escape(r.actions)}</div></div>`:''}<div class="decision-meta flex flex-wrap justify-between items-center gap-3"><span>${icon('send')} Ответ опубликован ${fmt(r.closedAt||r.created)}</span>${role==='employee'&&!r.readByAuthor?btn('Ознакомился с результатом','ack','sm',`data-id="${r.id}"`):`<span>${icon(r.readByAuthor?'check-check':'inbox')} ${r.readByAuthor?'Автор ознакомился':'Доступен в кабинете автора'}</span>`}</div></section>`:''}<section class="card detail-block"><h2>Обращение сотрудника</h2><p class="body-copy">${escape(r.description)}</p>${r.proposed?`<div class="proposed"><h3>ПРЕДЛАГАЕМОЕ РЕШЕНИЕ АВТОРА</h3><p class="body-copy">${escape(r.proposed)}</p></div>`:''}${r.attachments.length?`<div class="attachments">${r.attachments.map((a,i)=>btn(icon('file')+escape(a.name),'download-file','',`data-id="${r.id}" data-index="${i}"`)).join('')}</div>`:''}</section>${!closed(r)?`<section class="card detail-block"><div class="flex justify-between items-center gap-3"><h2 style="margin:0">Следующий шаг</h2><span class="tiny-pill">${r.status==='waiting'?'Со стороны автора':r.owner?'Со стороны ответственного':'Со стороны администратора'}</span></div><p class="body-copy" style="margin-top:12px">${escape(r.nextAction||'Рассмотреть обращение и определить дальнейшие действия.')}</p>${r.decision?`<div class="proposed"><h3>ПРИНЯТОЕ РЕШЕНИЕ</h3><p class="body-copy">${escape(r.decision)}</p></div>`:''}${editable?`<div class="action-strip">${r.status==='new'?btn(icon('play')+'Взять на рассмотрение','start','primary',`data-id="${r.id}"`):btn(icon('circle-check-big')+'Зафиксировать решение','decision','primary',`data-id="${r.id}"`)}${r.status!=='waiting'?btn(icon('message-circle-question')+'Запросить уточнение','question','',`data-id="${r.id}"`):''}${r.status==='new'?btn('Решение','decision','',`data-id="${r.id}"`):''}</div><p class="form-hint">Решение и выполненные действия увидит автор. Изменения сохранятся в истории.</p>`:''}</section>`:''}<section class="card"><div class="card-head"><div><h2>Обсуждение и история</h2><p>Контекст сохраняется на всём пути обращения</p></div><span class="tiny-pill">${r.history.length} событий</span></div><div class="timeline">${r.history.map(h=>`<div class="timeline-event"><span class="timeline-dot">${icon(h.kind==='decision'?'check':h.kind==='comment'||h.kind==='question'?'message-circle':h.kind==='route'?'git-branch':'circle-dot')}</span><div class="event-meta">${escape(h.actor)} · ${fmt(h.at)} в ${time(h.at)}</div><p>${escape(h.text)}</p></div>`).join('')}</div>${!closed(r)&&role!=='admin'?`<form id="comment-form" class="comment-box" data-id="${r.id}"><label class="form-label" for="comment-text">${role==='employee'&&r.status==='waiting'?'Ответить на уточнение':'Добавить комментарий'}</label><textarea class="form-field" id="comment-text" name="comment" required minlength="3" maxlength="3000" placeholder="${role==='employee'?'Добавьте контекст или ответьте на вопрос…':'Комментарий будет виден автору обращения…'}"></textarea><div class="flex justify-between items-center gap-3"><span class="form-hint">Виден участникам обращения</span><button type="submit" class="btn primary">${icon('send')} ${role==='employee'&&r.status==='waiting'?'Отправить уточнение':'Отправить'}</button></div></form>`:''}</section></div><aside class="sticky-aside space-y-5"><section class="card detail-aside"><h2>Ответственность и срок</h2>${editable?'<form id="assignment-form">':''}<div class="properties"><dl class="property"><dt>ОТВЕТСТВЕННЫЙ</dt><dd>${editable?`<select name="owner" aria-label="Ответственный" required>${opts(owners,r.owner)}</select>`:r.owner?`<div class="flex gap-2 items-center"><span class="avatar small">${initials(r.owner)}</span>${escape(r.owner)}</div>`:'<span class="amber">Не назначен · резервная очередь</span>'}</dd></dl><dl class="property"><dt>СРОК РАССМОТРЕНИЯ</dt><dd>${editable?`<input type="date" name="due" aria-label="Срок рассмотрения" required value="${r.due}" min="${TODAY}">`:(closed(r)?fmt(r.due):dueLabel(r))}${overdue(r)?'<div class="form-hint red">Срок нарушен. Нужна реакция руководителя.</div>':''}</dd></dl><dl class="property"><dt>ПРИОРИТЕТ</dt><dd>${editable?`<select name="priority" aria-label="Приоритет">${opts(['Низкий','Средний','Высокий'],r.priority)}</select>`:escape(r.priority)}</dd></dl><dl class="property"><dt>НАПРАВЛЕНИЕ</dt><dd>${escape(r.direction)}</dd></dl><dl class="property"><dt>ПОДРАЗДЕЛЕНИЕ АВТОРА</dt><dd>${escape(r.department)}</dd></dl></div>${editable?`<input type="hidden" name="recordId" value="${r.id}"><button class="btn w-full" type="submit">Сохранить назначение</button></form>`:''}</section><section class="card flow-preview"><div class="flex gap-2 items-center">${icon('shield-check','brand')}<h2>Доступ к обращению</h2></div><p class="form-hint" style="margin-top:10px">Автор, ответственный, руководитель направления и администратор. Другие сотрудники не видят содержание.</p></section>${r.related.length?`<section class="card flow-preview"><div class="flex gap-2 items-center">${icon('layers-2','brand')}<h2>Общая тема</h2></div><p class="form-hint">Полнота постановки задач. Связь подтверждена в демонстрационных данных; у каждого автора сохраняется свой ответ.</p>${r.related.map(id=>{const linked=db.records.find(r=>r.id===id);return linked&&readable(linked)?`<button class="btn ghost sm" data-action="open" data-id="${id}">${id} · ${escape(linked.title)} ${icon('arrow-up-right')}</button>`:'';}).join('')}</section>`:''}</aside></div>`;
  }
  function analytics(){const rows=visible(),done=rows.filter(complete),finished=rows.filter(r=>closed(r)&&r.closedAt),inTime=finished.filter(r=>r.closedAt.slice(0,10)<=r.due),first=rows.filter(r=>r.firstResponse).map(r=>(new Date(r.firstResponse)-new Date(r.created))/3600000),duration=finished.map(r=>(new Date(r.closedAt)-new Date(r.created))/86400000),related=rows.filter(r=>r.related.length);const typeCounts=['Проблема','Предложение','Положительный отзыв'].map(type=>[type,rows.filter(r=>r.type===type).length]);
    return `${titleBlock('ДАННЫЕ ДЛЯ УЛУЧШЕНИЙ','Видеть причины. Менять процессы.','Скорость рассмотрения, повторяющиеся проблемы и подтверждённые результаты.',btn(icon('download')+'Экспорт обращений','export-all'))}${scope()}<div class="metric-grid grid grid-cols-4 gap-4 mb-5">${metric('Среднее время рассмотрения',avg(duration)+' <span style="font-size:13px">дн.</span>',`${finished.length} завершённых обращений`,'timer','nav','data-to="results"')}${metric('Рассмотрено в срок',pct(inTime.length,finished.length),`${inTime.length} из ${finished.length} завершённых`,'calendar-check-2','nav','data-to="results"','green')}${metric('С зафиксированным решением',pct(done.length,rows.length),`${done.length} решений на ${rows.length} обращений`,'clipboard-check','nav','data-to="results"')}${metric('Реализовано улучшений',rows.filter(r=>r.status==='implemented').length,'есть результат и описание действий','lightbulb','filter','data-filter="implemented"','green')}</div><div class="settings-grid mb-5"><section class="card"><div class="card-head"><div><h2>Обращения по типам</h2><p>Какая обратная связь приходит от сотрудников</p></div>${icon('chart-no-axes-column','muted')}</div><div class="px-5 pb-4">${typeCounts.map(([type,count])=>`<div class="chart-bar"><span>${type}</span><div class="chart-track"><span style="width:${rows.length?count/rows.length*100:0}%"></span></div><strong class="mono">${count}</strong></div>`).join('')}</div><div class="stat-definition">Среднее время первого ответа: <strong class="brand">${avg(first)} ч.</strong> · ${first.length} обращений с ответом руководителя.</div></section><section class="card"><div class="card-head"><div><h2>Результаты рассмотрения</h2><p>Решение зафиксировано и опубликовано автору</p></div>${icon('circle-check-big','green')}</div><div class="px-5 pb-4">${[['Реализовано','implemented'],['Отклонено с причиной','rejected'],['Закрыто с ответом','closed']].map(([label,s])=>{const count=rows.filter(r=>r.status===s).length;return `<div class="chart-bar"><button data-action="filter" data-filter="${s}">${label}</button><div class="chart-track green-track"><span style="width:${done.length?count/done.length*100:0}%"></span></div><strong class="mono">${count}</strong></div>`;}).join('')}</div><div class="stat-definition">Доля завершённых: <strong class="green">${pct(finished.length,rows.length)}</strong>. Ознакомились с итогом: ${done.filter(r=>r.readByAuthor).length} авторов.</div></section></div><div class="settings-grid"><section class="card"><div class="card-head"><div><h2>Категории обращений</h2><p>Нажмите на категорию для перехода к обращениям</p></div></div><div class="px-5 pb-4">${Object.entries(rows.reduce((a,r)=>(a[r.category]=(a[r.category]||0)+1,a),{})).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([cat,count])=>`<div class="chart-bar"><button data-action="category-filter" data-category="${escape(cat)}">${escape(cat)}</button><div class="chart-track"><span style="width:${rows.length?count/rows.length*100:0}%"></span></div><strong class="mono">${count}</strong></div>`).join('')}</div></section><section class="card"><div class="card-head"><div><h2>Повторяющиеся проблемы</h2><p>Подтверждённые связи между обращениями</p></div>${icon('layers-2','brand')}</div><div class="px-5 pb-5"><div class="analytics-number mono">${pct(related.length,rows.length)}</div><p class="subtle">${related.length} из ${rows.length} обращений связаны общей темой</p>${related.length?`<div class="proposed"><h3>ПОЛНОТА ПОСТАНОВКИ ЗАДАЧ</h3><p class="body-copy">В заявках и поручениях не хватает данных для начала работы. Общая точка улучшения — обязательные поля и шаблон.</p>${btn('Открыть связанные обращения '+icon('arrow-up-right'),'related','ghost sm')}</div>`:'<p class="form-hint">Подтверждённых повторов в этом направлении пока нет.</p>'}<p class="form-hint" style="margin-top:15px">Совпадение категории не считается доказанным повтором. Связи добавляются руководителем.</p></div></section></div><div class="card mt-5 p-5"><h2 style="font-size:12px;font-weight:700">Как считаются показатели</h2><p class="form-hint">Рассмотрение: от регистрации до итогового статуса. В срок: итог опубликован не позднее даты рассмотрения. С решением: итоговый статус и заполненный результат / все доступные обращения. Повторяемость: обращения с подтверждённой связью / все доступные обращения. Целевые значения компания определяет после пилота. Все даты в макете демонстрационные.</p></div>`;
  }
  function categories(){return `${titleBlock('УПРАВЛЕНИЕ СИСТЕМОЙ','Категории, понятные сотрудникам.','Категория помогает описать тему и найти нужного ответственного.',btn(icon('plus')+'Добавить категорию','add-category','primary'))}<div class="attention-banner purple">${icon('info')}<div>Категории берутся из демонстрационного датасета. Настройте маршрут для каждой категории, доступной в форме подачи.</div></div><section class="card"><div class="card-head"><h2>Категории обращений <span class="tiny-pill ml-2">${db.rules.length}</span></h2></div><div class="table-scroll"><table class="case-table settings-table"><thead><tr><th>КАТЕГОРИЯ</th><th>НАПРАВЛЕНИЕ</th><th>ОБРАЩЕНИЯ</th><th>ДОСТУПНОСТЬ</th><th></th></tr></thead><tbody>${db.rules.map(r=>`<tr><td><span class="flex items-center gap-2">${icon('tag','brand')}${escape(r.category)}</span></td><td class="muted">${escape(r.direction)}</td><td>${db.records.filter(c=>c.category===r.category).length}</td><td><span class="badge ${r.archived?'rejected':r.active?'implemented':'waiting'}">${r.archived?'В архиве':r.active?'Маршрут настроен':'Резервная очередь'}</span></td><td>${btn(icon('pencil'),'edit-category','sm',`data-id="${r.id}" aria-label="Изменить категорию ${escape(r.category)}"`)}</td></tr>`).join('')}</tbody></table></div></section>`;}
  function routing(){const unassigned=db.records.filter(r=>!r.owner&&!closed(r));return `${titleBlock('УПРАВЛЕНИЕ СИСТЕМОЙ','Правильный адресат. С первого раза.','Категория → направление → ответственный → срок рассмотрения.',btn(icon('plus')+'Новое правило','add-rule','primary'))}${unassigned.length?`<section class="card mb-5" style="border-color:#ecdbc2"><div class="card-head"><div><h2 class="amber">${icon('git-pull-request')} Резервная очередь · ${unassigned.length}</h2><p>Правило отсутствует или неактивно. Обращения сохранены и ждут назначения.</p></div></div>${unassigned.map(r=>`<div class="px-5 pb-5 flex justify-between items-center gap-3"><div><button class="case-title" data-action="open" data-id="${r.id}">${escape(r.title)}</button><div class="case-caption">${r.id} · ${escape(r.category)}</div></div>${btn('Назначить маршрут '+icon('arrow-right'),'assign','sm',`data-id="${r.id}"`)}</div>`).join('')}</section>`:`<div class="attention-banner green-banner">${icon('circle-check-big')}Все активные обращения имеют ответственного.</div>`}<section class="card"><div class="card-head"><div><h2>Правила маршрутизации</h2><p>Изменения применяются к новым обращениям. Существующие назначения сохраняются.</p></div><span class="tiny-pill">${db.rules.filter(r=>r.active&&!r.archived).length} активных</span></div><div class="table-scroll"><table class="case-table settings-table"><thead><tr><th>КАТЕГОРИЯ</th><th>НАПРАВЛЕНИЕ И ОТВЕТСТВЕННЫЙ</th><th>СРОК</th><th>ПРАВИЛО</th><th></th></tr></thead><tbody>${db.rules.filter(r=>!r.archived).map(r=>`<tr><td>${escape(r.category)}</td><td><div style="font-size:11px">${escape(r.direction)}</div><div class="case-caption">${r.owner?escape(r.owner):'Назначение администратором'}</div></td><td class="muted">${r.days} дн.</td><td><span class="badge ${r.active?'implemented':'waiting'}">${r.active?'Активно':'Резерв'}</span></td><td>${btn(icon('sliders-horizontal'),'edit-rule','sm',`data-id="${r.id}" aria-label="Настроить маршрут ${escape(r.category)}"`)}</td></tr>`).join('')}</tbody></table></div></section><div class="card mt-5 p-5"><div class="flex items-center gap-2"><h2 style="font-size:12px;font-weight:700">Защита от потери обращения</h2>${icon('shield-check','brand')}</div><p class="form-hint">Если правило не найдено, выключено или не содержит ответственного, обращение попадает в резерв. Администратор получает уведомление. Срок первичного назначения в макете — один календарный день; руководитель затем уточняет срок рассмотрения.</p></div>${db.audit.length?`<section class="card mt-5"><div class="card-head"><h2>История настроек</h2></div><div class="timeline">${db.audit.slice().reverse().slice(0,8).map(a=>`<div class="timeline-event"><span class="timeline-dot">${icon('settings-2')}</span><div class="event-meta">${fmt(a.at)} · Администратор</div><p>${escape(a.text)}</p></div>`).join('')}</div></section>`:''}`;}
  function notificationView(){const all=notifications();return `${titleBlock('ОБРАТНАЯ СВЯЗЬ БЕЗ ПОТЕРЬ','Уведомления','Изменения статуса, новые уточнения и результаты рассмотрения.',all.some(n=>!n.read)?btn(icon('check-check')+'Отметить прочитанными','read-notifications'):'')}<section class="card">${all.length?all.map(n=>`<button class="notification ${n.read?'':'unread'}" data-action="read-notification" data-id="${n.id}"><span class="type-icon idea">${icon('bell')}</span><div class="flex-1"><div class="flex justify-between gap-3"><h3>${escape(n.title)}</h3><span class="case-id">${n.caseId}</span></div><p>${escape(n.text)}</p><time>Демонстрационный период · ноябрь 2026</time></div>${icon('arrow-up-right','muted')}</button>`).join(''):empty('Новых уведомлений нет','Здесь появятся изменения по доступным вам обращениям.','bell')}</section>`;}
  function help(){return `${titleBlock('IDEAROUTE · ИНТЕРАКТИВНЫЙ МАКЕТ','От идеи к результату.','Enterprise Feedback & Case Management · внутренний процесс обратной связи.',btn('Начать сценарий','demo-start','primary'))}<div class="settings-grid mb-5"><section class="card help-section"><h2>Проверьте сквозной сценарий</h2><ol><li>Выберите роль «Сотрудник», откройте «Новое обращение». Заполните пример и зарегистрируйте его.</li><li>Переключитесь на «Руководитель». Найдите новое обращение в направлении «Операционные процессы».</li><li>Начните рассмотрение, запросите уточнение. От роли сотрудника ответьте в карточке.</li><li>Вернитесь к руководителю. Зафиксируйте решение и выполненные действия либо мотивированный отказ.</li><li>В роли сотрудника откройте уведомление и ознакомьтесь с результатом.</li></ol></section><section class="card help-section"><h2>Границы макета</h2><p>Это локальный интерактивный прототип на HTML и Tailwind v4. Все 20 исходных обращений — синтетические примеры из «Датасет.docx». Даты, сроки, связи и события добавлены для демонстрации.</p><p style="margin-top:12px">Данные хранятся только в этом браузере. Переключатель ролей иллюстрирует права доступа; реальной авторизации и серверной защиты нет. Уведомления работают внутри макета; письма и сообщения не отправляются. Вложения сохраняются локально.</p><p style="margin-top:12px">Клиентский портал, NPS, опросы и интеграции с 1С / Битрикс24 относятся к дальнейшему развитию. AI не требуется для прохождения основного сценария.</p>${btn('Сбросить демо-данные','reset-dialog','sm mt-4')}</section></div><section class="card"><div class="card-head"><div><h2>Покрытие ТЗ и Business Vision</h2><p>Основа: DOCX ТЗ ГК «Модус Трейд» и Business Vision IdeaRoute из задания.</p></div></div><div class="table-scroll"><table class="case-table coverage"><thead><tr><th>ТРЕБОВАНИЕ</th><th>ГДЕ ПРОВЕРИТЬ</th><th>РЕЗУЛЬТАТ ДЛЯ ПОЛЬЗОВАТЕЛЯ</th></tr></thead><tbody>${[['ТЗ §2.2 · роли','Переключатель сотрудник / руководитель / администратор','Разные действия и области видимости'],['ТЗ §2.3 · регистрация','Новое обращение: категория, тип, описание, решение, материалы','Номер, маршрут, срок и запись в моих обращениях'],['ТЗ §2.3–2.5 · рассмотрение','Реестр → карточка → назначение, уточнение, решение','История и понятный следующий шаг'],['ТЗ §2.5 · отсутствие потерь','Маршрутизация → резервная очередь','Ручное назначение, если нет правила'],['ТЗ §2.4 · сроки и поиск','Реестр → фильтры и карточка','Просрочки, поиск по тексту и контроль сроков'],['ТЗ §2.6 · конфиденциальность','Разные роли и прямой переход к недоступной карточке','Сотрудник видит свои, руководитель — своё направление'],['ТЗ §2.7 · бизнес-ценность','Аналитика и связанные обращения','Решения, время ответа, время рассмотрения, повторы'],['Business Vision · Closed Loop','Карточка → результат → уведомление → автор','Решение и действия зафиксированы, автор видит итог'],['ТЗ §3.2 · интерактивность','Форма, таблица / доска, карточка, настройки','Ключевой сценарий проходит от начала до конца'],['ТЗ §3.5 и §4.2 · ограничения','Этот раздел и локальная инструкция','Отделены работающий прототип, имитации и будущие функции'],['ТЗ §3.6 · развитие','Концепция: права на сервере, хранилище, уведомления, интеграции','Промышленный контур требует отдельной реализации']].map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="card help-section mt-5"><h2>Что считать завершённым циклом</h2><p>Итоговый статус + содержательное решение + доступный автору результат. «Реализовано» также содержит описание выполненных действий. Отметка «Ознакомился» показывает прочтение, но не блокирует завершение процесса. Отказ с понятной причиной — тоже результат рассмотрения.</p><h2 style="margin-top:18px">Техническая концепция следующего этапа</h2><p>Веб-интерфейс → серверная проверка пользователя и прав → база обращений, категорий, назначений и событий. Файлы — в закрытом хранилище. Регистрация, маршрут и событие истории сохраняются атомарно. Уведомления отправляются через надёжную очередь. Назначения и сроки контролируются фоновыми задачами. Интеграции требуют отдельного согласования состава данных.</p></section>`;}
  function render(){getRoute();try{sessionStorage.setItem('idearoute-maket-context',JSON.stringify({role,direction}));}catch{}const views={overview,cases,new:newCase,case:detail,results,analytics,categories,routing,notifications:notificationView,help};el('app').innerHTML=shell(views[view]());document.title=(view==='case'?selectedId+' · ':'')+'IdeaRoute — от идеи к результату';hydrate();}
  function refreshResults(){if(!el('case-results'))return;el('case-results').innerHTML=tableOrBoard();el('result-count').textContent=`Найдено ${filtered().length} из ${visible().length}`;hydrate();}
  function openModal(title,body,footer='',formId=''){lastModalFocus=document.activeElement;el('modal').innerHTML=`${formId?`<form id="${formId}">`:''}<div class="modal-head"><h2 id="modal-title">${title}</h2><button type="button" class="icon-button" data-action="close-modal" aria-label="Закрыть окно">${icon('x')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}${formId?'</form>':''}`;el('modal').showModal();document.body.classList.add('modal-open');hydrate();}
  function closeModal(){el('modal').close();document.body.classList.remove('modal-open');if(lastModalFocus?.isConnected)lastModalFocus.focus();}
  const cancel=()=>btn('Отмена','close-modal','','type="button"');
  const submit=text=>`<button class="btn primary" type="submit">${text}</button>`;
  function decisionModal(r){if(!manageable(r)||closed(r))return;openModal('Зафиксировать решение',`<p class="modal-desc">${r.id} · ${escape(r.title)}<br>Автор увидит решение и дальнейшие действия в своём кабинете.</p><input type="hidden" name="recordId" value="${r.id}"><div class="field-group"><label class="form-label" for="decision-outcome">Результат рассмотрения</label><select class="form-field" name="outcome" id="decision-outcome"><option value="progress">Принято — передать в работу</option><option value="implemented">Реализовано — действия выполнены</option><option value="rejected">Отклонено — с объяснением причины</option><option value="closed">Закрыто — ответ предоставлен</option></select></div><div class="field-group"><label class="form-label" for="decision-text">Решение для автора <span class="brand">*</span></label><textarea id="decision-text" class="form-field" name="decision" required minlength="10" maxlength="4000" rows="4" placeholder="Что решили и почему? Объясните результат понятным языком.">${escape(r.decision)}</textarea></div><div class="field-group" id="action-field"><label class="form-label" id="action-label" for="decision-actions">Дальнейшие действия <span class="brand">*</span></label><textarea id="decision-actions" class="form-field" name="actions" required minlength="8" maxlength="3000" rows="3" placeholder="Какие действия будут выполнены, кем и к какому сроку?"></textarea></div><div id="decision-deadline"><label class="form-label" for="decision-due">Срок выполнения <span class="brand">*</span></label><input id="decision-due" name="due" type="date" class="form-field" min="${TODAY}" required value="${r.due<TODAY?TODAY:r.due}"></div><p class="form-hint" style="margin-top:15px">Передача в работу сохраняет цикл открытым. Итоговые статусы публикуют результат и создают уведомление автору.</p>`,cancel()+submit('Опубликовать решение'),'decision-form');}
  function questionModal(r){if(!manageable(r)||closed(r)||r.status==='waiting')return;openModal('Запросить уточнение',`<p class="modal-desc">Автор получит уведомление, а статус изменится на «Ожидает уточнения». После ответа обращение вернётся к рассмотрению.</p><input type="hidden" name="recordId" value="${r.id}"><label class="form-label" for="question-text">Что нужно уточнить?</label><textarea id="question-text" class="form-field" name="question" required minlength="10" maxlength="3000" rows="4" placeholder="Например, каких параметров чаще всего не хватает? Приведите один пример."></textarea>`,cancel()+submit('Отправить запрос'),'question-form');}
  function ruleModal(rule){if(role!=='admin')return;openModal(rule?'Настроить маршрут':'Новое правило',`<p class="modal-desc">Правило применяется при регистрации нового обращения. Сроки в макете — демонстрационные, в календарных днях.</p><input type="hidden" name="recordId" value="${rule?.id||''}"><div class="field-group"><label class="form-label" for="rule-category">Категория</label><select class="form-field" id="rule-category" name="category" required>${opts(db.rules.filter(r=>!r.archived).map(r=>r.category),rule?.category)}</select></div><div class="field-group"><label class="form-label" for="rule-direction">Направление</label><select id="rule-direction" class="form-field" name="direction">${opts(['Операционные процессы','IT и данные'],rule?.direction||'Операционные процессы')}</select></div><div class="field-group"><label class="form-label" for="rule-owner">Ответственный</label><select class="form-field" id="rule-owner" name="owner" required>${opts(owners,rule?.owner,'Выберите ответственного')}</select></div><div class="field-group"><label class="form-label" for="rule-days">Срок рассмотрения, календарных дней</label><input type="number" class="form-field" id="rule-days" name="days" required min="1" max="90" value="${rule?.days||3}"></div><label class="flex items-center gap-2" style="font-size:11px"><input type="checkbox" name="active" ${rule?.active!==false?'checked':''}>Правило активно</label><p class="form-hint">Выключенное правило направляет новые обращения в резервную очередь.</p>`,cancel()+submit('Сохранить правило'),'rule-form');}
  function categoryModal(rule){if(role!=='admin')return;openModal(rule?'Изменить категорию':'Новая категория',`<input type="hidden" name="recordId" value="${rule?.id||''}"><div class="field-group"><label class="form-label" for="category-name">Название категории</label><input id="category-name" class="form-field" name="category" required minlength="3" maxlength="80" value="${escape(rule?.category||'')}" placeholder="Например, рабочее оборудование"></div><div class="field-group"><label class="form-label" for="category-direction">Направление</label><select id="category-direction" class="form-field" name="direction">${opts(['Операционные процессы','IT и данные'],rule?.direction||'Операционные процессы')}</select></div>${rule?`<label class="flex items-center gap-2" style="font-size:11px"><input type="checkbox" name="archived" ${rule.archived?'checked':''}>Убрать из формы новых обращений</label>`:''}<p class="form-hint">${rule?'История и существующие обращения сохранятся. Переименование обновит название категории в связанных карточках.':'После создания настройте правило маршрутизации. До этого обращения попадут в резервную очередь.'}</p><div id="category-error" role="alert"></div>`,cancel()+submit('Сохранить категорию'),'category-form');}
  function assignModal(r){if(role!=='admin'||r.owner)return;openModal('Назначить маршрут обращения',`<p class="modal-desc">${r.id} · ${escape(r.title)}<br>Назначение выведет обращение из резервной очереди.</p><input type="hidden" name="recordId" value="${r.id}"><div class="field-group"><label class="form-label" for="assign-direction">Направление</label><select id="assign-direction" class="form-field" name="direction">${opts(['Операционные процессы','IT и данные'],r.direction)}</select></div><div class="field-group"><label class="form-label" for="assign-owner">Ответственный</label><select id="assign-owner" class="form-field" name="owner" required>${opts(owners,'','Выберите ответственного')}</select></div><div class="field-group"><label class="form-label" for="assign-due">Срок рассмотрения</label><input id="assign-due" name="due" type="date" class="form-field" required min="${TODAY}" value="2026-11-15"></div><p class="form-hint">Действие фиксируется в истории. Чтобы следующие обращения находили адресата автоматически, настройте правило для категории.</p>`,cancel()+submit('Назначить ответственного'),'assign-form');}
  function setFilter(value){if(view!=='cases')filters={q:'',status:'',category:'',department:'',deadline:''};filters.status='';filters.deadline='';if(['overdue','today','unassigned'].includes(value))filters.deadline=value;else filters.status=value;go('cases');}
  function download(filename,content,type='text/plain;charset=utf-8'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
  function exportRows(rows){const quote=v=>{let s=String(v??'');if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const data=[['Номер','Тема','Тип','Категория','Подразделение','Статус','Ответственный','Срок','Решение','Действия'],...rows.map(r=>[r.id,r.title,r.type,r.category,r.department,statuses[r.status],r.owner,r.due,r.decision,r.actions])].map(row=>row.map(quote).join(';')).join('\r\n');download('IdeaRoute-'+TODAY+'.csv','\uFEFF'+data,'text/csv;charset=utf-8');toast(`Экспортировано обращений: ${rows.length}`);}
  document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target)return;const a=target.dataset.action,r=target.dataset.id?db.records.find(r=>r.id===target.dataset.id):null;
    switch(a){
      case 'skip':e.preventDefault();el('main').focus();break;
      case 'nav':mobileOpen=false;go(target.dataset.to);break;
      case 'menu':mobileOpen=!mobileOpen;document.querySelector('.sidebar').classList.toggle('open',mobileOpen);document.querySelector('.mobile-scrim').classList.toggle('open',mobileOpen);document.querySelector('.mobile-menu').setAttribute('aria-expanded',mobileOpen);break;
      case 'open':if(r&&readable(r))go('case/'+r.id);break;
      case 'filter':setFilter(target.dataset.filter);break;
      case 'queue':if(role==='admin')setFilter('unassigned');else if(role==='employee')setFilter('waiting');else {activeTab='attention';filters={q:'',status:'open',category:'',department:'',deadline:''};go('cases');}break;
      case 'overview-tab':activeTab=target.dataset.tab;render();break;
      case 'table-view':board=false;render();break;
      case 'board-view':board=true;render();break;
      case 'clear-filters':filters={q:'',status:'',category:'',department:'',deadline:''};render();break;
      case 'category-filter':filters={q:'',status:'',category:target.dataset.category,department:'',deadline:''};go('cases');break;
      case 'related':filters={q:'',status:'',category:'__related',department:'',deadline:''};go('cases');break;
      case 'search':go('cases');requestAnimationFrame(()=>el('case-search')?.focus());break;
      case 'sample':{const f=el('new-case-form');if(!f)break;f.elements.category.value='Межотдельное взаимодействие';f.elements.type.value='Проблема';f.elements.title.value='Обязательные параметры в заявке на оборудование';f.elements.description.value='В заявках на приобретение оборудования иногда не хватает назначения изделия и требуемых параметров. Приходится запрашивать уточнения и откладывать закупку.';f.elements.proposed.value='Добавить в форму заявки обязательные поля: назначение изделия, параметры и ожидаемый срок.';saveDraft();el('route-preview').innerHTML=routePreview(f.elements.category.value);hydrate();toast('Пример заполнен. Проверьте поля и зарегистрируйте обращение.');break;}
      case 'remove-file':attachments.splice(Number(target.dataset.index),1);el('new-attachments').innerHTML=attachmentDraft();saveDraft();hydrate();break;
      case 'start':if(r&&manageable(r)&&r.status==='new'){r.status='review';r.firstResponse||=NOW;r.nextAction='Изучить ситуацию, уточнить необходимые данные и зафиксировать решение.';event(r,'Обращение принято к рассмотрению. Ответственный изучает ситуацию.');notify(r,'employee','Обращение принято к рассмотрению',`${r.id} · ${r.owner}. Срок: ${fmt(r.due)}.`);save();render();toast('Рассмотрение началось. Автор получил уведомление.');}break;
      case 'decision':if(r)decisionModal(r);break;
      case 'question':if(r)questionModal(r);break;
      case 'close-modal':closeModal();break;
      case 'focus-comment':el('comment-text')?.focus();el('comment-text')?.scrollIntoView({behavior:'smooth',block:'center'});break;
      case 'ack':if(r&&role==='employee'&&readable(r)&&complete(r)&&!r.readByAuthor){r.readByAuthor=true;event(r,'Автор ознакомился с результатом рассмотрения.','read');db.notifications.filter(n=>n.role==='employee'&&n.caseId===r.id).forEach(n=>n.read=true);notify(r,'manager','Автор ознакомился с результатом',r.title);save();render();toast('Отметка об ознакомлении сохранена.');}break;
      case 'download-file':if(r&&readable(r)){const file=r.attachments[Number(target.dataset.index)];if(file){const link=document.createElement('a');link.href=file.data;link.download=file.name;document.body.append(link);link.click();link.remove();}}break;
      case 'export':exportRows(filtered());break;
      case 'export-all':exportRows(visible());break;
      case 'add-category':categoryModal(null);break;
      case 'edit-category':categoryModal(db.rules.find(r=>r.id===target.dataset.id));break;
      case 'add-rule':ruleModal(null);break;
      case 'edit-rule':ruleModal(db.rules.find(r=>r.id===target.dataset.id));break;
      case 'assign':if(r)assignModal(r);break;
      case 'read-notification':{const n=notifications().find(n=>n.id===target.dataset.id);if(n){n.read=true;save();go('case/'+n.caseId);}break;}
      case 'read-notifications':notifications().forEach(n=>n.read=true);save();render();toast('Уведомления отмечены прочитанными.');break;
      case 'demo-start':role='employee';go('new');break;
      case 'reset-dialog':openModal('Начать демонстрацию заново?',`<p class="modal-desc">Будут восстановлены 20 исходных обращений. Созданные в этом макете карточки, черновик и настройки маршрутов удалятся из памяти браузера. Это действие касается только демонстрации.</p>`,cancel()+btn('Сбросить демо','reset-confirm','danger','type="button"'));break;
      case 'reset-confirm':db=structuredClone(window.IDEAROUTE_SEED);try{localStorage.removeItem(DRAFT);}catch{}save();closeModal();role='manager';direction='Операционные процессы';filters={q:'',status:'',category:'',department:'',deadline:''};activeTab='attention';board=false;go('overview');toast('Исходная демонстрация восстановлена.');break;
    }
  });
  document.addEventListener('input',e=>{if(e.target.id==='case-search'){filters.q=e.target.value;refreshResults();}if(e.target.closest('#new-case-form'))saveDraft();});
  document.addEventListener('change',async e=>{const t=e.target;
    if(t.dataset.change==='role'){role=t.value;mobileOpen=false;filters={q:'',status:'',category:'',department:'',deadline:''};activeTab='attention';go('overview');return;}
    if(t.dataset.change==='direction'){direction=t.value;filters={q:'',status:'',category:'',department:'',deadline:''};render();return;}
    if(t.dataset.filterField){filters[t.dataset.filterField]=t.value;refreshResults();return;}
    if(t.id==='new-category'){el('route-preview').innerHTML=routePreview(t.value);saveDraft();hydrate();return;}
    if(t.id==='decision-outcome'){const isProgress=t.value==='progress',isImplemented=t.value==='implemented';el('decision-actions').required=isProgress||isImplemented;el('action-label').innerHTML=(isImplemented?'Что выполнено':isProgress?'Дальнейшие действия':'Дополнительный контекст')+((isProgress||isImplemented)?' <span class="brand">*</span>':' · необязательно');el('decision-actions').placeholder=isImplemented?'Опишите фактически выполненные действия и полученный результат.':isProgress?'Какие действия будут выполнены, кем и к какому сроку?':'При необходимости добавьте объяснение.';el('decision-deadline').hidden=!isProgress;el('decision-due').required=isProgress;return;}
    if(t.closest('#rule-form')&&t.name==='active'){el('rule-owner').required=t.checked;return;}
    if(t.id==='new-files'){
      const files=[...t.files];if(files.length+attachments.length>3){toast('Можно приложить не больше 3 файлов.');t.value='';return;}
      for(const file of files){if(file.size>1048576){toast('Файл '+file.name+' превышает 1 МБ.');continue;}if(!/\.(pdf|png|jpg|jpeg|txt|docx|xlsx)$/i.test(file.name)){toast('Этот формат файла не поддерживается.');continue;}try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});attachments.push({name:file.name,size:file.size,data});}catch{toast('Не удалось прочитать файл '+file.name);}}
      if(el('new-attachments')){el('new-attachments').innerHTML=attachmentDraft();t.value='';saveDraft();hydrate();}
    }
  });
  document.addEventListener('submit',e=>{const form=e.target;if(!['new-case-form','comment-form','assignment-form','decision-form','question-form','rule-form','category-form','assign-form'].includes(form.id))return;e.preventDefault();if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));for(const key of Object.keys(data))if(typeof data[key]==='string')data[key]=data[key].trim();const r=db.records.find(r=>r.id===data.recordId||r.id===form.dataset.id);
    if(form.id==='new-case-form'){
      if(role!=='employee')return;if(data.title.length<5||data.description.length<15){el('form-error').innerHTML='<p class="form-error">Добавьте содержательную тему и описание ситуации.</p>';return;}
      const rule=routeFor(data.category);const next=Math.max(...db.records.map(r=>Number(r.id.slice(2))))+1,id='A-'+String(next).padStart(3,'0');const due=new Date(TODAY+'T12:00:00Z');due.setUTCDate(due.getUTCDate()+(rule?rule.days:1));
      const record={id,type:data.type,category:data.category,title:data.title,description:data.description,proposed:data.proposed,author:identities.employee,department:'Закупки',priority:'Средний',owner:rule?.owner||'',direction:rule?.direction||db.rules.find(r=>r.category===data.category)?.direction||'Операционные процессы',status:'new',created:NOW,due:due.toISOString().slice(0,10),firstResponse:null,closedAt:null,decision:'',actions:'',nextAction:rule?'Ответственный рассмотрит обращение и определит дальнейшие действия.':'Администратор назначит ответственного из резервной очереди.',readByAuthor:false,attachments:structuredClone(attachments),related:[],history:[{at:NOW,actor:identities.employee,text:'Обращение зарегистрировано. Категория: '+data.category+'.',kind:'created'},{at:NOW,actor:'Система',text:rule?`Маршрут: ${rule.direction} → ${rule.owner}. Срок рассмотрения: ${fmt(due.toISOString().slice(0,10))}.`:'Маршрут не найден. Обращение сохранено в резервной очереди. Администратор уведомлён.',kind:'route'}]};
      db.records.unshift(record);notify(record,rule?'manager':'admin',rule?'Новое обращение в вашем направлении':'Обращение ожидает назначения',record.title);notify(record,'employee','Обращение зарегистрировано',`${id} · ${rule?'Назначен '+rule.owner:'Администратор определит ответственного'}.`);save();try{localStorage.removeItem(DRAFT);}catch{}attachments=[];go('case/'+id);toast(`${id} зарегистрировано. ${rule?'Ответственный получил уведомление.':'Администратор получил уведомление.'}`);return;
    }
    if(form.id==='comment-form'){
      if(!r||!readable(r)||role==='admin'||closed(r)||data.comment.length<3)return;event(r,data.comment,'comment');if(role==='employee'&&r.status==='waiting'){r.status='review';r.nextAction='Уточнение получено. Рассмотреть ответ автора и продолжить работу.';event(r,'Уточнение отправлено. Обращение возвращено на рассмотрение.');notify(r,'manager','Автор ответил на уточнение',r.title);}else {if(role==='manager')r.firstResponse||=NOW;notify(r,role==='employee'?'manager':'employee','Новый комментарий',r.title);}save();render();toast('Комментарий сохранён в истории.');return;
    }
    if(form.id==='assignment-form'){
      if(!r||!manageable(r)||closed(r))return;const oldOwner=r.owner,oldDue=r.due,oldPriority=r.priority;r.owner=data.owner;r.due=data.due;r.priority=data.priority;event(r,`Назначение обновлено: ${oldOwner} → ${r.owner}; срок: ${fmt(oldDue)} → ${fmt(r.due)}; приоритет: ${oldPriority} → ${r.priority}.`,'route');notify(r,'employee','Обновлены ответственный или срок',`${r.id} · ${r.owner}. Срок: ${fmt(r.due)}.`);save();render();toast('Ответственный, срок и приоритет сохранены.');return;
    }
    if(form.id==='question-form'){
      if(!r||!manageable(r)||closed(r)||r.status==='waiting')return;if(data.question.length<10){toast('Уточните вопрос: нужно не менее 10 символов.');return;}r.status='waiting';r.firstResponse||=NOW;r.nextAction=data.question;event(r,data.question,'question');notify(r,'employee','Нужен ваш ответ',data.question);save();closeModal();render();toast('Запрос отправлен автору. История сохранена.');return;
    }
    if(form.id==='decision-form'){
      if(!r||!manageable(r)||closed(r))return;const requiresAction=['implemented','progress'].includes(data.outcome);if(data.decision.length<10||(requiresAction&&data.actions.length<8)){toast('Опишите решение и конкретные действия.');return;}r.status=data.outcome;r.decision=data.decision;r.actions=data.actions;r.firstResponse||=NOW;r.readByAuthor=false;r.nextAction=data.outcome==='progress'?data.actions:'Результат опубликован для автора.';if(data.outcome==='progress')r.due=data.due;else r.closedAt=NOW;event(r,`${statuses[r.status]}. ${r.decision}${r.actions?' Действия: '+r.actions:''}`,'decision');notify(r,'employee',closed(r)?'По вашему обращению есть результат':'По вашему обращению принято решение',r.decision);save();closeModal();render();toast(closed(r)?'Результат опубликован. Автор получил уведомление.':'Решение зафиксировано. Работа продолжается.');return;
    }
    if(form.id==='rule-form'){
      if(role!=='admin')return;const rule=db.rules.find(r=>r.category===data.category);if(!rule)return;const enabled=Boolean(data.active);if(enabled&&!data.owner){toast('Для активного правила нужен ответственный.');return;}rule.direction=data.direction;rule.owner=data.owner;rule.days=Math.max(1,Math.min(90,Number(data.days)));rule.active=enabled;db.audit.push({at:NOW,text:`Маршрут «${rule.category}»: ${rule.direction} → ${rule.owner||'резервная очередь'}; ${rule.days} дн.; ${enabled?'активен':'выключен'}.`});save();closeModal();render();toast('Правило сохранено для новых обращений.');return;
    }
    if(form.id==='category-form'){
      if(role!=='admin')return;if(data.category.length<3){toast('Введите название категории.');return;}if(db.rules.some(r=>r.id!==data.recordId&&r.category.toLowerCase()===data.category.toLowerCase())){el('category-error').innerHTML='<p class="form-error">Категория с таким названием уже существует.</p>';return;}let rule=db.rules.find(r=>r.id===data.recordId);if(rule){const old=rule.category;db.records.filter(r=>r.category===old).forEach(r=>{r.category=data.category;});rule.category=data.category;rule.direction=data.direction;rule.archived=!!data.archived;}else {rule={id:'rule-'+Date.now(),category:data.category,direction:data.direction,owner:'',days:3,active:false,archived:false};db.rules.push(rule);}db.audit.push({at:NOW,text:`Категория «${rule.category}» ${data.recordId?'обновлена':'создана'}. ${rule.archived?'Скрыта из формы новых обращений.':''}`});save();closeModal();render();toast('Категория сохранена.');return;
    }
    if(form.id==='assign-form'){
      if(role!=='admin'||!r||r.owner||closed(r))return;r.owner=data.owner;r.direction=data.direction;r.due=data.due;r.nextAction='Ответственный назначен. Обращение ожидает рассмотрения.';event(r,`Назначено вручную из резервной очереди: ${r.direction} → ${r.owner}. Срок: ${fmt(r.due)}.`,'route');notify(r,'manager','Обращение направлено вам',r.title);notify(r,'employee','Назначен ответственный',`${r.owner}. Срок рассмотрения: ${fmt(r.due)}.`);save();closeModal();render();toast('Обращение передано ответственному.');return;
    }
  });
  el('modal').addEventListener('close',()=>document.body.classList.remove('modal-open'));
  el('modal').addEventListener('click',e=>{if(e.target===el('modal')){const box=el('modal').getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)closeModal();}});
  document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!el('modal').open){e.preventDefault();go('cases');requestAnimationFrame(()=>el('case-search')?.focus());}if(e.key==='Escape'&&mobileOpen){mobileOpen=false;render();}});
  window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
  render();
})();
